    when(textExtractor.extractContent(any(), any(), any())).thenReturn(new ParsedContent("first attachment content", ImmutableMap.of())).thenThrow(new RuntimeException("second cannot be parsed")).thenReturn(new ParsedContent("third attachment content", ImmutableMap.of()));
    // When
    IndexableMessage indexableMessage = IndexableMessage.from(mailboxMessage, ImmutableList.of(new MockMailboxSession("username").getUser()), textExtractor, ZoneId.of("Europe/Paris"), IndexAttachments.YES);
