@Test
public void applyPatternShouldModifyWhenMatchingBody() throws Exception {
    GenericMailet mailet = mock(GenericMailet.class);
    ContentReplacer testee = new ContentReplacer(false, mailet);
    Mail mail = mock(Mail.class);
    MimeMessage mimeMessage = mock(MimeMessage.class);
    when(mail.getMessage()).thenReturn(mimeMessage);
    when(mimeMessage.getContent()).thenReturn("test aa o");
    when(mimeMessage.getContentType()).thenReturn("text/plain");
    ImmutableList<ReplacingPattern> patterns = ImmutableList.of(new ReplacingPattern(Pattern.compile("test"), false, "TEST"), new ReplacingPattern(Pattern.compile("a"), true, "e"), new ReplacingPattern(Pattern.compile("o"), false, "o"));
    ReplaceConfig replaceConfig = ReplaceConfig.builder().addAllBodyReplacingUnits(patterns).build();
    testee.replaceMailContentAndSubject(mail, replaceConfig, Optional.of(Charsets.UTF_8));
    verify(mimeMessage).setContent("TEST ee o", "text/plain; charset=UTF-8");
}

