public void processShouldWork() throws Exception {
    MoveRequest moveRequest = new MoveRequest(ImapCommand.anyStateCommand("Name"), new IdRange[] { new IdRange(4, 6) }, ImapConstants.INBOX_NAME, true, TAG);
