@Test
public void errorsShouldBeWellHandled() throws Exception {
    MailDispatcher testee = MailDispatcher.builder().log(mock(Log.class)).mailetContext(fakeMailContext).mailStore(mailStore).consume(true).build();
    doThrow(new MessagingException()).when(mailStore).storeMail(any(MailAddress.class), any(Mail.class));
    MimeMessage mimeMessage = MimeMessageBuilder.mimeMessageBuilder().setMultipartWithBodyParts(MimeMessageBuilder.bodyPartBuilder().data("toto").build()).build();
    FakeMail mail = FakeMail.builder().sender(MailAddressFixture.OTHER_AT_JAMES).mimeMessage(mimeMessage).recipients(MailAddressFixture.ANY_AT_JAMES).state("state").build();
    testee.dispatch(mail);
    List<FakeMailContext.SentMail> actual = fakeMailContext.getSentMails();
    FakeMailContext.SentMail expected = FakeMailContext.sentMailBuilder().sender(MailAddressFixture.OTHER_AT_JAMES).recipient(MailAddressFixture.ANY_AT_JAMES).state(Mail.ERROR).build();
    assertThat(actual).containsOnly(expected);
    assertThat(IOUtils.toString(actual.get(0).getMsg().getInputStream(), Charsets.UTF_8)).contains("toto");
}

@Test
public void dispatchShouldUpdateReturnPath() throws Exception {
    MailDispatcher testee = MailDispatcher.builder().log(mock(Log.class)).mailetContext(fakeMailContext).mailStore(mailStore).consume(false).build();
    FakeMail mail = FakeMail.builder().sender(MailAddressFixture.OTHER_AT_JAMES).recipients(MailAddressFixture.ANY_AT_JAMES).mimeMessage(MimeMessageBuilder.defaultMimeMessage()).state("state").build();
    testee.dispatch(mail);
    ArgumentCaptor<Mail> mailCaptor = ArgumentCaptor.forClass(Mail.class);
    verify(mailStore).storeMail(any(MailAddress.class), mailCaptor.capture());
    assertThat(mailCaptor.getValue().getMessage().getHeader(RFC2822Headers.RETURN_PATH)).containsExactly("<" + MailAddressFixture.OTHER_AT_JAMES + ">");
}

