@Before
public void setup() throws Exception {
    requestHandler = mock(RequestHandler.class);
    JMAPServlet jmapServlet = new JMAPServlet(requestHandler);
    server = JettyHttpServer.create(Configuration.builder().serve("/*").with(jmapServlet).randomPort().build());
    server.start();
    RestAssured.requestSpecification = new RequestSpecBuilder().setContentType(ContentType.JSON).setAccept(ContentType.JSON).setConfig(newConfig().encoderConfig(encoderConfig().defaultContentCharset(Charsets.UTF_8))).setPort(server.getPort()).build();
}

@Test
public void mustReturnInvalidArgumentOnInvalidState() {
    ObjectNode json = new ObjectNode(new JsonNodeFactory(false));
    json.put("type", "invalidArgument");
    when(requestHandler.handle(any())).thenReturn(Stream.of(new ProtocolResponse(ErrorResponse.ERROR_METHOD, json, ClientId.of("#0"))));
    given().body("[[\"getAccounts\", {\"state\":false}, \"#0\"]]").when().post("/").then().statusCode(200).content(equalTo("[[\"error\",{\"type\":\"invalidArgument\"},\"#0\"]]"));
}

@Test
public void mustReturnAccountsOnValidRequest() {
    ObjectNode json = new ObjectNode(new JsonNodeFactory(false));
    json.put("state", "f6a7e214");
    ArrayNode arrayNode = json.putArray("list");
    ObjectNode list = new ObjectNode(new JsonNodeFactory(false));
    list.put("id", "6asf5");
    list.put("name", "roger@barcamp");
    arrayNode.add(list);
    when(requestHandler.handle(any())).thenReturn(Stream.of(new ProtocolResponse(Method.Response.name("accounts"), json, ClientId.of("#0"))));
    given().body("[[\"getAccounts\", {}, \"#0\"]]").when().post("/").then().statusCode(200).content(equalTo("[[\"accounts\",{" + "\"state\":\"f6a7e214\"," + "\"list\":[" + "{" + "\"id\":\"6asf5\"," + "\"name\":\"roger@barcamp\"" + "}" + "]" + "},\"#0\"]]"));
}

@Test
public void createMailboxSessionShouldThrownWhenAuthHeadersIsInvalid() throws Exception {
    String username = "123456789";
    String validAuthHeader = "valid";
